mapper.select:
SELECT h.id, h.name, h.category_id AS categoryId, c.name AS categoryName, h.level, h.region, h.protection_unit AS protectionUnit, h.publish_time AS publishTime, h.description, h.history, h.cover_image AS coverImage, h.view_count AS viewCount, h.favorite_count AS favoriteCount, h.create_time AS createTime FROM t_heritage h LEFT JOIN t_heritage_category c ON h.category_id = c.id WHERE h.deleted_flag = 0
AND (h.name LIKE CONCAT('%', #{query.keyword}, '%') OR h.description LIKE CONCAT('%', #{query.keyword}, '%'))
AND h.category_id = #{query.categoryId}
AND h.level = #{query.level}
AND h.region LIKE CONCAT('%', #{query.region}, '%')
ORDER BY h.sort ASC, h.create_time DESC
